                 fragment_head *frag_msg;

                 /* Check if it's the last packet */
                 if (!(pinfo->fd->visited)) {
                     iso15765_info->bytes_used = data_length;

-                    /* Update the last_frag_id */
-                    if (frag_id > iso15765_frame->last_frag_id) {
